from pathlib import Path
p=Path('/mnt/data/parkchaeeun-ai-lab');a=p/'assets'
css=r'''@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;600;700;800;900&display=swap');:root{--blue:#4357cb;--indigo:#293da8;--teal:#079d90;--text:#1d2b44;--muted:#6c7891;--bg:#f4f7fd;--line:#e0e7f4;--white:#fff;--soft:#edf1ff;--shadow:0 8px 32px rgba(27,49,102,.055)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:'Noto Sans KR','Apple SD Gothic Neo',sans-serif;background:var(--bg);color:var(--text);font-size:15px;line-height:1.75}a{text-decoration:none;color:inherit}button,select,input{font:inherit}button{border:0;cursor:pointer;border-radius:11px;padding:11px 17px;font-weight:800;background:var(--blue);color:white}button:hover:not(:disabled){filter:brightness(.94);transform:translateY(-1px)}button:disabled{opacity:.43;cursor:not-allowed}.btn-soft{background:#e8ecff;color:#3449ab}.btn-outline{background:white;color:var(--blue);border:1px solid #b7c4f7}.btn-teal{background:#087f79}.container{max-width:1120px;margin:auto;padding:0 25px}.topbar{position:sticky;top:0;z-index:20;background:#ffffffed;backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.navwrap{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:25px}.logo{font-weight:900;white-space:nowrap;color:var(--indigo);font-size:18px;letter-spacing:-.7px}.logo small{display:block;font-weight:600;letter-spacing:0;color:var(--muted);font-size:10px;line-height:1.3}.topnav{display:flex;flex-wrap:wrap;gap:4px}.topnav a{font-size:12px;font-weight:800;border-radius:10px;padding:9px 11px;color:#53607a}.topnav a:hover,.topnav a.active{background:var(--soft);color:var(--indigo)}.author{position:fixed;right:12px;bottom:18px;background:#fff;padding:7px 11px;border:1px solid #dae2fa;border-radius:30px;font-size:11px;font-weight:800;box-shadow:var(--shadow);color:var(--indigo);z-index:30}.hero{background:linear-gradient(130deg,#243a91,#495bd2 61%,#0e969a);color:#fff;padding:68px 0 74px}.hero h1{font-size:clamp(27px,4.4vw,49px);letter-spacing:-1.8px;line-height:1.35;margin:16px 0}.hero p{color:#eef2ff;max-width:760px;line-height:1.9}.chip{display:inline-block;border-radius:40px;background:#ffffff24;padding:5px 12px;font-size:12px;font-weight:800;margin-right:6px}.subhero{background:linear-gradient(120deg,#2c429c,#5366c9);color:white;padding:38px 0 42px}.subhero h1{font-size:32px;letter-spacing:-1px;margin:6px 0}.subhero p{color:#e3e9ff;margin:0}.crumb{font-size:12px;opacity:.85;font-weight:700}.content{padding:40px 0 90px}.sec{margin:28px 0 42px;scroll-margin-top:90px}.sec h2{font-size:24px;margin:4px 0 14px;letter-spacing:-.6px}.eyebrow{font-size:12px;color:var(--blue);font-weight:900;letter-spacing:.13em;text-transform:uppercase}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.card{background:#fff;border-radius:18px;border:1px solid var(--line);padding:23px;box-shadow:var(--shadow)}.card h3{margin:6px 0 10px;font-size:18px}.card p{margin:9px 0}.linkcard{display:block;transition:.2s;position:relative}.linkcard:hover{transform:translateY(-4px);box-shadow:0 12px 30px #293da818;border-color:#bdc9fa}.linkcard:after{content:'학습하러 가기 →';font-size:12px;display:block;margin-top:18px;font-weight:900;color:var(--blue)}.icon{font-size:30px}.num{font-size:12px;color:var(--blue);font-weight:900}.pill{display:inline-block;background:#e9eeff;color:#3850b0;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:800}.callout{padding:16px 18px;background:#edf9f7;border-left:4px solid var(--teal);border-radius:10px;margin:16px 0}.callout.warn{background:#fff7e9;border-left-color:#d4a143}.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.row.between{justify-content:space-between}.lessonsteps{display:flex;gap:8px;align-items:stretch;flex-wrap:wrap}.lessonsteps .item{flex:1;min-width:140px;padding:17px;background:#eef2ff;border-radius:12px;text-align:center;font-weight:800}.lessonsteps .item span{font-size:11px;display:block;color:#5b6ca7;margin-top:4px}.lessonsteps .arrow{font-size:22px;color:var(--blue);align-self:center}.tablewrap{width:100%;overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{border-bottom:1px solid var(--line);padding:10px 12px;text-align:left}th{background:#edf2fd;color:#364d8b;font-weight:800}tr:last-child td{border-bottom:0}select,input[type=number]{padding:10px 13px;border:1px solid #cfdaf1;border-radius:9px;background:#fff;color:var(--text);max-width:100%}input[type=range]{accent-color:var(--blue);min-width:145px}input[type=checkbox]{accent-color:var(--blue)}.buttons{display:flex;gap:9px;flex-wrap:wrap;margin:14px 0}.task{border-radius:14px;background:#f3f6ff;padding:16px 18px;margin:12px 0}.task .tag{color:var(--blue);font-size:11px;font-weight:900}.task p{margin:6px 0}.result{background:#f0f7ff;border:1px solid #d6e5fb;padding:14px 16px;border-radius:10px;min-height:51px}.success{color:#078d70;font-weight:800}.danger{color:#cf4958;font-weight:800}.warning{color:#ad7511;font-weight:800}.progress{height:9px;background:#e3e9f5;border-radius:10px;overflow:hidden}.progress span{display:block;background:linear-gradient(90deg,var(--blue),var(--teal));height:100%;transition:width .2s}.stepnav{display:flex;gap:9px;flex-wrap:wrap}.stepnav button{flex:1;min-width:125px;background:#e9eeff;color:#4356ad}.stepnav button.active{background:var(--blue);color:white}.panel[hidden]{display:none}.statgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{padding:14px;background:#f2f5ff;border-radius:11px}.stat strong{display:block;font-size:24px;color:var(--indigo)}.stat small{color:var(--muted);font-size:11px}.canvas{display:block;width:100%;max-width:650px;background:#fafcff;border:1px solid var(--line);border-radius:12px}.option{display:block;width:100%;text-align:left;padding:12px 14px;margin:8px 0;background:#f0f3fc;color:var(--text);border:1px solid #dbe3f4}.option.selected{background:#dde5ff;border-color:var(--blue)}.option.correct{background:#e4f7f0;border-color:#31b28c}.option.incorrect{background:#fff0f1;border-color:#ed929e}.qfeedback{font-size:13px;font-weight:700;color:var(--indigo);min-height:28px}.switches{display:flex;gap:9px;flex-wrap:wrap}.switches button{background:#edf1ff;color:var(--indigo)}.switches button.active{background:var(--blue);color:white}.footer{background:#23335c;color:#d8e0f4;padding:34px 0}.footer small{color:#afbddb}.codeword{background:#edf1f9;border:1px solid #e0e6f2;border-radius:5px;font-size:12px;padding:2px 5px}.taglist{display:flex;gap:7px;flex-wrap:wrap}.taglist span{border-radius:7px;padding:5px 9px;background:#e9efff;font-size:12px;font-weight:700}.checkline{border:1px solid #e0e7f4;border-radius:10px;padding:12px 14px;margin:9px 0;background:#fafcff}.right{text-align:right}.center{text-align:center}.hidden{display:none!important}footer a{text-decoration:underline}@media(max-width:850px){.grid,.grid.two{grid-template-columns:1fr}.navwrap{align-items:flex-start;flex-direction:column;padding:12px 25px;gap:9px}.topnav a{padding:7px 9px}.statgrid{grid-template-columns:repeat(2,1fr)}.author{bottom:10px;right:7px}.hero{padding:42px 0}}@media print{.topbar,.author,.buttons,button,.footer{display:none!important}.card{break-inside:avoid}}
'''
(a/'style.css').write_text(css)
NAV=[('index.html','홈'),('types.html','① 기계학습 유형'),('workflow.html','② 모델 구현'),('lab.html','③ 스팸 분류 실험'),('review.html','④ 정리·퀴즈')]
def page(name,title,subtitle,body,script=''):
 nav=''.join(f'<a class="{"active" if name==u else ""}" href="{u}">{t}</a>' for u,t in NAV)
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#4357cb"><title>{title} | 박채은 AI LAB</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><div class="container navwrap"><a class="logo" href="index.html">🤖 박채은 AI LAB<small>인공지능 기초 · 기계학습 알고리즘</small></a><nav class="topnav">{nav}</nav></div></header><div class="author">made by 박채은</div>{f'<div class="subhero"><div class="container"><div class="crumb">HOME / 인공지능 기초 / Ⅱ. 인공지능과 학습</div><h1>{title}</h1><p>{subtitle}</p></div></div>' if name!='index.html' else ''}<main>{body}</main><footer class="footer"><div class="container"><b>🤖 박채은 AI LAB</b><div>고등학교 2학년 · 인공지능 기초 교과서 88–92쪽 · made by 박채은</div><small>학습용 모의 데이터와 시뮬레이션을 사용합니다. 원본 참고 사이트의 콘텐츠·코드를 복제하지 않았습니다.</small></div></footer><script src="assets/common.js"></script>{f'<script src="assets/{script}"></script>' if script else ''}</body></html>'''
index='''<section class="hero"><div class="container"><span class="chip">고등학교 2학년</span><span class="chip">교과서 88~92쪽</span><span class="chip">15분 모의수업</span><h1>AI는 어떻게<br>스팸 메일을 구분할까?</h1><p>기계학습의 유형을 이해하고, 실제로 데이터를 준비해 모델을 학습시킨 뒤 새로운 메일에 대한 예측을 평가해 봅니다. 각 학습 카드를 클릭하면 독립된 페이지에서 자세히 학습할 수 있습니다.</p><a href="types.html"><button style="background:#fff;color:#2e43ad">학습 시작하기 →</button></a></div></section><div class="container content"><section class="sec"><div class="eyebrow">Today's goals</div><h2>🎯 오늘의 학습목표</h2><div class="grid"><div class="card"><span class="pill">01</span><h3>기계학습 유형</h3><p>지도학습·비지도학습·강화학습을 사례로 구분한다.</p></div><div class="card"><span class="pill">02</span><h3>모델 구현 단계</h3><p>문제 정의부터 모델 평가까지 네 단계를 설명한다.</p></div><div class="card"><span class="pill">03</span><h3>훈련과 평가</h3><p>훈련·테스트 데이터를 구분하고 예측 성능을 해석한다.</p></div></div></section><section class="sec"><div class="eyebrow">Choose a chapter</div><h2>📚 학습 내용</h2><p class="muted">참고 사이트처럼 카드를 클릭하면 각각 다른 페이지로 이동합니다.</p><div class="grid two"><a class="card linkcard" href="types.html"><div class="icon">🧠</div><div class="num">CHAPTER 01 · 교과서 88~91쪽</div><h3>기계학습의 세 가지 유형</h3><p>지도학습·비지도학습·강화학습을 비교하고, 분류·회귀·군집·연관 규칙을 사례에 적용합니다.</p><span class="pill">상황 카드 분류 실습</span></a><a class="card linkcard" href="workflow.html"><div class="icon">🛠️</div><div class="num">CHAPTER 02 · 교과서 92쪽</div><h3>모델의 학습과 평가</h3><p>문제 정의→데이터 준비→모델 생성→평가. 데이터 전처리와 훈련·테스트 데이터의 역할을 확인합니다.</p><span class="pill">4단계 순서 탐구</span></a><a class="card linkcard" href="lab.html"><div class="icon">🔬</div><div class="num">CHAPTER 03 · 핵심 시연 실습</div><h3>스팸 메일 분류 실험실</h3><p>정답 레이블 확인, 학습 데이터 구성, 실제 분류기 학습, 테스트 결과 분석, 오분류 개선까지.</p><span class="pill">브라우저에서 실제 계산</span></a><a class="card linkcard" href="review.html"><div class="icon">🏆</div><div class="num">CHAPTER 04 · 형성평가</div><h3>핵심 정리와 확인 퀴즈</h3><p>학습지에서 확인할 핵심 내용과 자체 연습 퀴즈. 모의수업 마지막에는 Kahoot!으로 마무리합니다.</p><span class="pill">정답 및 해설</span></a></div></section><section class="sec"><div class="card"><div class="row between"><div><div class="eyebrow">15-minute teaching route</div><h2>⏱️ 모의수업 추천 동선</h2></div><span class="pill">실습 시연용</span></div><div class="lessonsteps"><div class="item">도입<span>2분</span></div><div class="item">기계학습 유형<span>4분</span></div><div class="item">모델 구현<span>2분</span></div><div class="item">스팸 모델 실습<span>4분</span></div><div class="item">정리·Kahoot!<span>3분</span></div></div><div class="callout">교사는 실습 페이지를 조작하고, 학생이 먼저 결과를 예측한 뒤 시연 결과를 확인하는 방식으로 진행합니다. 나머지 기능은 수업 후 자기주도 학습에 활용할 수 있습니다.</div></div></section></div>'''
(p/'index.html').write_text(page('index.html','홈','',index))
types='''<div class="container content"><section class="sec"><div class="eyebrow">01 · 개념 학습</div><h2>기계학습의 세 가지 학습 방식</h2><div class="grid"><div class="card"><div class="icon">🏷️</div><h3>지도학습</h3><p>데이터와 <b>정답 레이블</b>을 함께 사용해 학습하며, 새로운 데이터의 범주 또는 연속적인 수치를 예측합니다.</p><div class="taglist"><span>분류: 스팸/정상</span><span>회귀: 가격 예측</span></div></div><div class="card"><div class="icon">🧩</div><h3>비지도학습</h3><p><b>정답 레이블 없이</b> 데이터의 패턴과 구조를 찾아냅니다.</p><div class="taglist"><span>군집: 고객 그룹</span><span>연관 규칙: 함께 구매</span></div></div><div class="card"><div class="icon">🎮</div><h3>강화학습</h3><p>에이전트가 환경과 상호작용하며 행동에 따른 <b>보상</b>을 바탕으로 전략을 개선합니다.</p><div class="taglist"><span>행동</span><span>보상</span><span>시행착오</span></div></div></div></section><section class="sec"><div class="card"><h2>🔎 더 자세히: 분류·회귀·군집·연관 규칙</h2><div class="grid two"><div class="task"><b>분류 Classification</b><p>정해진 범주 중 하나 예측: 정상 메일 / 스팸 메일</p></div><div class="task"><b>회귀 Regression</b><p>연속적인 수치 예측: 기온, 배춧값, 판매량</p></div><div class="task"><b>군집 Clustering</b><p>비슷한 특징의 고객을 그룹으로 묶기</p></div><div class="task"><b>연관 규칙 Association</b><p>우유를 구매한 고객의 빵 동시 구매 패턴 찾기</p></div></div><div class="callout">교과서 89쪽의 지도학습 사례와 90쪽의 비지도학습 사례를 비교해 봅시다. 분류는 미리 정의된 범주에 예측하고, 군집은 정답 레이블 없이 그룹을 발견합니다.</div></div></section><section class="sec"><div class="eyebrow">Try it yourself</div><h2>🎯 학습 유형 선택 실습</h2><div class="card"><p class="muted">문제 상황을 읽고 적절한 학습 유형을 선택한 다음, 선택 이유를 확인하세요.</p><div class="row between"><span id="caseCounter" class="pill">1 / 5</span><button class="btn-soft" id="newCase">다른 상황 →</button></div><div class="task"><div class="tag">문제 상황</div><h3 id="caseText">로딩 중</h3></div><div class="grid" id="caseOptions"></div><div id="caseFeedback" class="result" aria-live="polite">먼저 학습 유형을 선택하세요.</div></div></section><section class="sec"><div class="card"><h2>🧪 비교 탐구: 분류와 군집은 무엇이 다를까?</h2><p>같은 고객 데이터를 보더라도 <b>정답 레이블로 정해진 범주를 예측하는 일</b>과 <b>유사한 특징을 가진 그룹을 찾아내는 일</b>은 다릅니다.</p><div class="switches"><button id="showClass" class="active">레이블 있는 분류 예시</button><button id="showCluster">레이블 없는 군집 예시</button></div><svg id="typeSVG" viewBox="0 0 620 260" style="width:100%;max-width:720px;margin-top:16px;background:#f8faff;border-radius:12px" role="img" aria-label="분류와 군집 개념 비교 그림"></svg><div id="typeExplain" class="callout">정답이 있는 데이터로 배운 모델이 새로운 데이터의 범주를 예측합니다.</div></div></section><div class="buttons"><a href="index.html"><button class="btn-outline">← 메인</button></a><a href="workflow.html"><button>다음: 모델 구현 과정 →</button></a></div></div>'''
(p/'types.html').write_text(page('types.html','Chapter 01. 기계학습의 유형','지도학습·비지도학습·강화학습과 대표 문제 해결 방식을 이해해 봅시다.',types,'types.js'))
workflow='''<div class="container content"><section class="sec"><div class="eyebrow">02 · 모델 구현 과정</div><h2>기계학습은 네 단계로 문제를 해결해요</h2><div class="card"><div class="lessonsteps"><div class="item">① 문제 정의<span>무엇을 해결할까?</span></div><div class="item">② 데이터 수집·전처리<span>어떻게 준비할까?</span></div><div class="item">③ 모델 생성<span>어떻게 학습할까?</span></div><div class="item">④ 모델 평가<span>얼마나 잘 예측할까?</span></div></div><div class="callout">스팸 메일 분류는 <b>지도학습의 분류</b> 문제입니다. 정답 레이블을 가진 메일 데이터로 모델을 학습시킨 뒤 별도 데이터로 평가합니다.</div></div></section><section class="sec"><div class="eyebrow">Explore the four steps</div><h2>🔍 각 단계를 눌러 자세히 살펴보기</h2><div class="card"><div id="workflowTabs" class="stepnav"><button data-n="0" class="active">① 문제 정의</button><button data-n="1">② 데이터 준비</button><button data-n="2">③ 모델 생성</button><button data-n="3">④ 모델 평가</button></div><div class="task"><h3 id="wfTitle"></h3><p id="wfBody"></p><div id="wfQuestion" class="callout"></div></div><div class="buttons"><button id="wfPrev" class="btn-outline">← 이전</button><button id="wfNext">다음 단계 →</button></div></div></section><section class="sec"><div class="grid two"><div class="card"><h2>📚 훈련 데이터</h2><p>모델에 입력하고 정답을 알려주어 <b>패턴을 학습시키기 위한 데이터</b>입니다.</p><div class="task">예: '무료 쿠폰 당첨' → 스팸</div></div><div class="card"><h2>📝 테스트 데이터</h2><p>학습에 사용하지 않은 <b>별도의 데이터</b>로 모델의 예측 결과와 정답을 비교하여 성능을 확인합니다.</p><div class="task">예: 새로운 메일의 스팸 여부 예측</div></div></div><div class="callout warn">학습 데이터에서 높은 점수를 받았다고 해서 처음 보는 데이터까지 잘 예측한다는 뜻은 아닙니다. 별도의 테스트 데이터로 확인해야 해요.</div></section><section class="sec"><div class="card"><h2>🧼 데이터 전처리 실험: 누락된 값 확인하기</h2><p>교과서 92쪽에 따르면 데이터를 수집한 다음 결측치·이상치를 확인하고, 필요한 특징을 추출합니다. 아래 예시에서 누락된 레이블을 찾아보세요.</p><div class="tablewrap"><table><thead><tr><th>메일</th><th>광고성 단어</th><th>일상 단어</th><th>레이블</th></tr></thead><tbody><tr><td>무료 쿠폰 안내</td><td>2</td><td>0</td><td>스팸</td></tr><tr><td>수행평가 일정</td><td>0</td><td>2</td><td>정상</td></tr><tr><td>당첨자 회의 안내</td><td>1</td><td>2</td><td id="missingLabel"><span class="danger">누락</span></td></tr></tbody></table></div><div class="buttons"><button id="inspectMissing">결측치 확인</button><button id="repairMissing" class="btn-soft">확인 후 레이블 검토하기</button></div><div id="prepResult" class="result" aria-live="polite">학습용 데이터에서 빠진 정보가 없는지 살펴보세요.</div></div></section><section class="sec"><div class="card"><h2>🧮 모델의 정확도</h2><p><b>정확도 = 올바르게 예측한 개수 ÷ 전체 예측 개수 × 100</b></p><div class="row"><label for="correctNum">맞힌 개수</label><input id="correctNum" type="number" min="0" max="10" value="3" style="width:80px"><label>전체</label><strong>4개</strong><button id="calcAccuracy">정확도 계산</button></div><div id="accuracyOut" class="result">4개 중 3개라면 정확도는 75%입니다.</div><p class="muted">이 지표 하나만으로 모든 실제 상황에서의 성능을 보장할 수는 없습니다.</p></div></section><div class="buttons"><a href="types.html"><button class="btn-outline">← 학습 유형</button></a><a href="lab.html"><button>다음: 스팸 분류 실습 →</button></a></div></div>'''
(p/'workflow.html').write_text(page('workflow.html','Chapter 02. 모델의 학습과 평가','교과서 92쪽의 네 단계와 데이터 전처리·훈련·테스트 데이터의 의미를 이해해 봅시다.',workflow,'workflow.js'))
lab='''<div class="container content"><section class="sec"><div class="eyebrow">03 · Main interactive laboratory</div><h2>🔬 스팸 메일 분류 모델 만들기</h2><p class="muted">수업의 핵심 실습입니다. 교과서 92쪽의 네 단계를 실제로 수행합니다. 정답 레이블과 단어 특징을 활용한 <b>교육용 나이브 베이즈 분류기</b>를 브라우저에서 직접 계산합니다. 고급 알고리즘을 외우는 것이 아니라, 훈련과 평가의 의미를 배우는 활동입니다.</p><div class="card"><div class="row between"><b>실습 진행</b><span id="stageCount" class="pill">1 / 4 단계</span></div><div class="progress"><span id="stageProgress" style="width:25%"></span></div><div class="stepnav" style="margin:18px 0"><button data-stage="0" class="active">① 문제 정의</button><button data-stage="1">② 데이터 준비</button><button data-stage="2">③ 모델 학습</button><button data-stage="3">④ 모델 평가</button></div>
<div class="panel" id="stage0"><h2>① 문제 정의: 해결하려는 문제는?</h2><div class="task"><span class="tag">상황</span><h3>메일함에 도착한 새 메시지가 '스팸'인지 '정상'인지 자동으로 분류하고 싶어요.</h3><p>정답이 표시된 과거 메일을 이용할 수 있습니다.</p></div><p><b>생각하기:</b> 어떤 학습 유형이 알맞을까요?</p><div class="switches" id="problemChoices"><button data-choice="supervised">지도학습</button><button data-choice="unsupervised">비지도학습</button><button data-choice="reinforcement">강화학습</button></div><div id="problemFeedback" class="result" style="margin-top:12px">먼저 유형을 선택하세요.</div><div class="buttons"><button data-next="1">데이터 준비 →</button></div></div>
<div class="panel" id="stage1" hidden><h2>② 데이터 준비: 훈련과 테스트를 나누자</h2><p>가상의 메일 제목을 <b>단어 목록</b>으로 나타낸 데이터입니다. 정답이 있는 훈련 데이터로 학습하고, 학습에 사용하지 않은 테스트 데이터로 평가합니다.</p><div class="row"><label for="datasetSize"><b>훈련 데이터 선택</b></label><select id="datasetSize"><option value="8">기본 8개 (각 범주 4개)</option><option value="16" selected>확장 16개 (각 범주 8개)</option></select><span class="pill">테스트 데이터 6개는 별도 유지</span></div><div class="tablewrap"><table><thead><tr><th>번호</th><th>메일 제목 (훈련 데이터)</th><th>정답 레이블</th><th>학습용 단어 특징</th></tr></thead><tbody id="trainRows"></tbody></table></div><div class="callout"><b>전처리:</b> 메일 제목에서 공백을 기준으로 단어를 추출하고, 같은 단어의 등장 여부를 특징으로 사용합니다. 이 수업 데이터는 사전에 오탈자와 누락 레이블을 확인한 가상의 예시입니다.</div><p>테스트 메일의 정답은 모델 예측을 마칠 때까지 숨깁니다.</p><div class="buttons"><button id="prepConfirm">데이터 구분 확인</button><button data-next="2">모델 학습 단계 →</button></div><div id="prepFeedback" class="result">서로 다른 용도의 훈련 데이터와 테스트 데이터를 확인하세요.</div></div>
<div class="panel" id="stage2" hidden><h2>③ 모델 생성: 실제로 모델을 학습시켜 보자</h2><p>버튼을 누르면 훈련 데이터의 단어 빈도를 세고, 범주별 단어 등장 패턴을 학습합니다. 사용한 알고리즘은 <b>다항 나이브 베이즈(Multinomial Naive Bayes)</b>의 간단한 교육용 구현입니다.</p><div class="buttons"><button id="trainModel">▶ 모델 학습하기</button><button id="resetModel" class="btn-outline">↺ 학습 초기화</button></div><div id="trainingFeedback" class="result">아직 모델을 학습하지 않았습니다.</div><div class="grid two" style="margin-top:16px"><div class="card" style="box-shadow:none"><h3>스팸에서 자주 나온 단어</h3><div id="spamWords" class="taglist"><span>학습 전</span></div></div><div class="card" style="box-shadow:none"><h3>정상에서 자주 나온 단어</h3><div id="hamWords" class="taglist"><span>학습 전</span></div></div></div><div class="callout warn">이 모형에서는 단어 빈도와 정답 레이블로 학습한 패턴을 이용합니다. 특정 단어 하나가 스팸 여부를 절대적으로 결정하는 것은 아닙니다.</div><div class="buttons"><button id="toEval" data-next="3" disabled>학습 완료 → 모델 평가하기</button></div></div>
<div class="panel" id="stage3" hidden><h2>④ 테스트 데이터로 모델 평가하기</h2><p>처음 보는 메일 6개를 예측해 봅시다. 먼저 예측만 확인한 뒤, 정답을 공개하여 정확도를 계산합니다.</p><div class="buttons"><button id="predictTests" disabled>📨 테스트 메일 예측하기</button><button id="revealAnswers" class="btn-teal" disabled>✅ 실제 정답 공개·평가</button><button id="resetTests" class="btn-outline">↺ 평가 초기화</button></div><div class="tablewrap"><table><thead><tr><th>메일</th><th>모델 예측</th><th>실제 정답</th><th>결과</th></tr></thead><tbody id="testRows"></tbody></table></div><div class="statgrid" style="margin-top:17px"><div class="stat"><small>테스트 메일</small><strong>6개</strong></div><div class="stat"><small>정답 개수</small><strong id="numCorrect">—</strong></div><div class="stat"><small>정확도</small><strong id="accuracy">—</strong></div><div class="stat"><small>오분류</small><strong id="numWrong">—</strong></div></div><div id="evalFeedback" class="callout">아직 평가하지 않았습니다. 예측부터 시작하세요.</div><div id="cm" hidden><h3>📊 혼동행렬: 어떤 종류의 실수를 했을까?</h3><p class="muted">행은 실제 정답, 열은 모델 예측입니다. 정확도 외에도 스팸을 놓쳤는지 정상 메일을 스팸으로 오인했는지 확인할 수 있습니다.</p><div class="tablewrap"><table><thead><tr><th>실제 \ 예측</th><th>스팸</th><th>정상</th></tr></thead><tbody id="cmRows"></tbody></table></div></div><div class="task"><div class="tag">생각해 보기</div><p>왜 훈련 데이터와 별도의 데이터로 평가할까요? 모델이 틀린 메일은 어떤 특징이 있었나요?</p></div></div>
</div></section><section class="sec"><div class="eyebrow">Advanced exploration</div><h2>🧪 추가 탐구: 모델이 왜 그렇게 예측했을까?</h2><div class="card"><p>모델 학습 후 직접 단어들을 선택하거나 메일 제목을 입력해 분류 결과를 확인해 보세요. <b>훈련 데이터가 8개일 때와 16개일 때 결과가 달라지는지도</b> 비교할 수 있어요.</p><div class="row"><label for="customText"><b>새 메일 제목</b></label><input id="customText" type="text" value="무료 쿠폰 당첨" style="flex:1;min-width:230px;padding:11px;border:1px solid #cfdaf1;border-radius:10px" maxlength="90"><button id="predictCustom" disabled>직접 분류</button></div><div class="row"><span class="muted">예시:</span><button class="btn-soft sample" data-text="무료 쿠폰 당첨">무료 쿠폰 당첨</button><button class="btn-soft sample" data-text="회의 일정 안내">회의 일정 안내</button><button class="btn-soft sample" data-text="무료 회의 쿠폰">무료 회의 쿠폰</button></div><div id="customFeedback" class="result">모델을 학습한 뒤 직접 분류할 수 있습니다.</div><div id="wordContributions" class="taglist" style="margin-top:12px"></div><p class="muted" style="font-size:12px">표시한 점수는 모델 내부 계산에서 정규화한 값입니다. 실제 이메일의 스팸일 확률을 보장하지 않으며, 훈련 자료의 단어에 따라 결과가 달라질 수 있습니다.</p></div></section><section class="sec"><div class="card"><h2>📖 실습 후 핵심 정리</h2><div class="grid"><div class="task"><b>정답 레이블</b><p>훈련 데이터의 스팸·정상 정답</p></div><div class="task"><b>모델 학습</b><p>훈련 데이터의 패턴을 이용해 분류 규칙 형성</p></div><div class="task"><b>모델 평가</b><p>새로운 테스트 데이터의 예측과 정답 비교</p></div></div><div class="callout">학습에 사용하지 않은 데이터로 모델을 평가하는 이유를 한 문장으로 설명할 수 있나요?</div></div></section><div class="buttons"><a href="workflow.html"><button class="btn-outline">← 모델 구현 과정</button></a><a href="review.html"><button>다음: 정리·퀴즈 →</button></a></div></div>'''
(p/'lab.html').write_text(page('lab.html','Chapter 03. 스팸 메일 분류 실험실','문제 정의, 데이터 준비, 실제 분류기 학습, 테스트 데이터 평가까지 순서대로 수행해 봅시다.',lab,'lab.js'))
review='''<div class="container content"><section class="sec"><div class="eyebrow">04 · Summary</div><h2>📘 15분 수업 핵심 정리</h2><div class="grid"><div class="card"><span class="pill">88~91쪽</span><h3>기계학습의 유형</h3><p>지도학습은 <b>정답 레이블</b>, 비지도학습은 <b>데이터의 패턴</b>, 강화학습은 <b>행동과 보상</b>을 중심으로 구분합니다.</p></div><div class="card"><span class="pill">92쪽</span><h3>모델의 구현 과정</h3><p>문제 정의 → 데이터 수집·전처리 → 모델 생성 → 모델 평가</p></div><div class="card"><span class="pill">핵심 실습</span><h3>훈련과 테스트</h3><p>훈련 데이터로 <b>학습</b>하고 별도 테스트 데이터로 <b>예측 성능</b>을 평가합니다.</p></div></div></section><section class="sec"><div class="card"><h2>✏️ 학습지 함께 확인하기</h2><p>교사가 학생과 함께 핵심 내용을 확인하는 정리 활동입니다.</p><div class="checkline">① 스팸 메일 분류는 ( <b>지도학습</b> )의 ( <b>분류</b> ) 문제이다.</div><div class="checkline">② 기계학습 모델 구현 과정은 ( <b>문제 정의</b> ) → ( <b>데이터 수집·전처리</b> ) → ( <b>모델 생성</b> ) → ( <b>모델 평가</b> )이다.</div><div class="checkline">③ 훈련 데이터는 ( <b>학습</b> )용, 테스트 데이터는 ( <b>평가</b> )용이다.</div></div></section><section class="sec"><div class="eyebrow">Knowledge check</div><h2>🏆 형성평가 연습 퀴즈</h2><p class="muted">모의수업 마지막에는 같은 핵심 문항을 Kahoot!에 옮겨 출제합니다. 이 페이지에서는 오답 피드백까지 확인할 수 있어요.</p><div id="quizMount"></div><div class="buttons"><button id="restartQuiz" class="btn-soft">퀴즈 다시 풀기</button><a href="https://create.kahoot.it/" target="_blank" rel="noopener"><button class="btn-outline">Kahoot! 교사용 편집 사이트 ↗</button></a></div><div id="quizSummary" class="callout">각 문항에 답하여 이해 정도를 확인하세요.</div></section><section class="sec"><div class="card"><h2>💬 마지막 생각거리</h2><p>모델의 정확도가 높게 나왔더라도 <b>처음 보는 다양한 메일</b>에도 잘 작동할까요? 어떤 데이터를 더 준비하면 좋을까요?</p><div class="callout warn">이번 실습의 데이터는 적은 수의 가상 예시입니다. 소수의 테스트 결과만으로 실제 모델의 성능을 확정하지 않습니다.</div></div></section><div class="buttons"><a href="lab.html"><button class="btn-outline">← 실습 다시 해보기</button></a><a href="index.html"><button>메인으로 돌아가기 →</button></a></div></div>'''
