(a/'common.js').write_text('''"use strict";const $=(q)=>document.querySelector(q),$$=(q)=>Array.from(document.querySelectorAll(q));''')
(a/'types.js').write_text(r'''"use strict";const cases=[{q:'정답이 표시된 메일 제목을 사용해 스팸/정상 여부를 예측하려고 합니다.',a:0,why:'정답 레이블이 있는 데이터를 이용해 정해진 범주를 예측하므로 지도학습의 분류입니다.'},{q:'정답 없이 고객의 구매 특성을 분석하여 비슷한 소비 유형끼리 묶으려고 합니다.',a:1,why:'정답 레이블이 없는 데이터의 유사한 특징을 탐색하므로 비지도학습의 군집입니다.'},{q:'게임 캐릭터가 여러 행동을 시도하고 얻는 점수를 통해 행동 전략을 개선합니다.',a:2,why:'행동에 따른 보상을 이용해 시행착오를 반복하므로 강화학습입니다.'},{q:'지난 몇 년간 기온과 강수량을 포함한 정답 수치 자료를 이용해 내일의 연속적인 배춧값을 예측합니다.',a:0,why:'정답 수치가 있는 데이터를 학습하여 연속적인 값을 예측하므로 지도학습의 회귀입니다.'},{q:'우유 구매 기록에서 함께 구매되는 빵·달걀 등 상품 사이의 관계를 찾아냅니다.',a:1,why:'상품 간의 관계를 발견하는 연관 규칙은 비지도학습의 예입니다.'}];let i=0;function showCase(){const c=cases[i];$('#caseCounter').textContent=`${i+1} / ${cases.length}`;$('#caseText').textContent=c.q;$('#caseFeedback').textContent='가장 적합한 학습 유형을 선택하고 이유를 생각하세요.';$('#caseOptions').innerHTML=['지도학습','비지도학습','강화학습'].map((x,k)=>`<button class="btn-soft" data-val="${k}">${x}</button>`).join('');$$('#caseOptions button').forEach(b=>b.onclick=()=>{const ok=+b.dataset.val===c.a;$('#caseFeedback').innerHTML=`<b class="${ok?'success':'danger'}">${ok?'정답!':'한 번 더 생각해 볼까요?'}</b> ${c.why}`;$$('#caseOptions button').forEach(x=>{x.style.outline=+x.dataset.val===c.a?'2px solid #079d90':'none'})})}$('#newCase').onclick=()=>{i=(i+1)%cases.length;showCase()};showCase();function draw(kind){const svg=$('#typeSVG');let str='';const pts=[[90,70],[117,88],[150,60],[129,112],[171,83],[382,165],[407,190],[435,157],[466,191],[449,133]];if(kind==='cluster'){str+='<ellipse cx="129" cy="86" rx="90" ry="65" fill="#dff7f1" stroke="#079d90" stroke-dasharray="6 5"/><ellipse cx="426" cy="165" rx="100" ry="72" fill="#e4eaff" stroke="#4357cb" stroke-dasharray="6 5"/>'}pts.forEach((p,k)=>{const color=k<5?'#079d90':'#4357cb';str+=`<circle cx="${p[0]}" cy="${p[1]}" r="9" fill="${color}"/>`;if(kind==='class')str+=`<text x="${p[0]+10}" y="${p[1]-10}" fill="${color}" font-size="11">${k<5?'A':'B'}</text>`});if(kind==='class')str+='<circle cx="285" cy="125" r="13" fill="white" stroke="#ef9e32" stroke-width="3"/><text x="281" y="130" font-size="17">?</text>';svg.innerHTML=str;$('#typeExplain').textContent=kind==='class'?'분류: 데이터에 알려진 범주 A·B를 학습해 새로운 데이터(?)가 어느 범주에 속하는지 예측합니다.':'군집: 정답 레이블 없이 데이터의 유사성을 바탕으로 그룹을 발견하는 개념적 시각화입니다.';$('#showClass').classList.toggle('active',kind==='class');$('#showCluster').classList.toggle('active',kind==='cluster')}$('#showClass').onclick=()=>draw('class');$('#showCluster').onclick=()=>draw('cluster');draw('class');''')
(a/'workflow.js').write_text(r'''"use strict";const steps=[['① 문제 정의하기','해결할 문제와 목표를 명확하게 정합니다. 예: 새 메일의 스팸·정상 여부를 예측하고 싶다.','어떤 입력 데이터와 출력 범주가 필요할까요?'],['② 데이터 수집 및 전처리하기','메일과 정답 레이블을 준비하고 누락된 값·이상치를 확인합니다. 필요하면 핵심 특징을 추출합니다.','정답 레이블이 빠진 메일이 있다면 바로 학습에 사용할 수 있을까요?'],['③ 모델 생성하기','문제에 맞는 학습 유형과 알고리즘을 선택한 뒤 훈련 데이터로 모델을 학습합니다.','스팸 메일 문제는 지도학습의 분류에 해당합니다.'],['④ 모델 평가하기','학습에 사용하지 않은 테스트 데이터로 예측 결과와 실제 정답을 비교하고 필요할 때 모델을 수정합니다.','훈련 데이터만 이용해 성능을 확인하면 어떤 한계가 있을까요?']];let n=0;function render(){const s=steps[n];$('#wfTitle').textContent=s[0];$('#wfBody').textContent=s[1];$('#wfQuestion').textContent='💬 '+s[2];$$('#workflowTabs button').forEach((b,j)=>b.classList.toggle('active',j===n));$('#wfPrev').disabled=n===0;$('#wfNext').textContent=n===3?'처음으로 ↺':'다음 단계 →'}$$('#workflowTabs button').forEach(b=>b.onclick=()=>{n=+b.dataset.n;render()});$('#wfPrev').onclick=()=>{n=Math.max(0,n-1);render()};$('#wfNext').onclick=()=>{n=(n+1)%4;render()};render();$('#inspectMissing').onclick=()=>{$('#prepResult').innerHTML='<b class="danger">발견!</b> 세 번째 메일의 정답 레이블이 누락되었습니다. 확인되지 않은 레이블을 임의로 정하면 잘못된 학습이 이루어질 수 있습니다.'};$('#repairMissing').onclick=()=>{$('#prepResult').innerHTML='<b class="success">좋아요.</b> 실제 정답을 원본 기록에서 확인하거나 적절하게 처리해야 합니다. 제목만으로 정답을 임의로 채우지는 않습니다.'};$('#calcAccuracy').onclick=()=>{const x=Number($('#correctNum').value);$('#accuracyOut').textContent=Number.isInteger(x)&&x>=0&&x<=4?`4개 중 ${x}개를 맞혔으므로 정확도는 ${(100*x/4).toFixed(0)}%입니다.`:'0부터 4 사이의 정수를 입력하세요.'};''')
(a/'lab.js').write_text(r'''"use strict";
// Balanced fictional training messages. Data remains local and fixed for repeatable lessons.
const DATA=[
 ['무료 쿠폰 당첨','스팸'],['특가 할인 이벤트','스팸'],['경품 당첨 안내','스팸'],['쿠폰 무료 혜택','스팸'],
 ['회의 일정 공유','정상'],['수업 과제 안내','정상'],['친구 약속 확인','정상'],['팀 프로젝트 회의','정상'],
 ['오늘 한정 무료 혜택','스팸'],['이벤트 참여 경품','스팸'],['특가 쿠폰 받기','스팸'],['무료 할인 쿠폰','스팸'],
 ['내일 수업 자료','정상'],['회의 자료 공유','정상'],['과제 제출 일정','정상'],['프로젝트 자료 확인','정상']];
const TEST=[['무료 혜택 안내','스팸'],['회의 일정 확인','정상'],['쿠폰 할인 이벤트','스팸'],['과제 제출 자료','정상'],['무료 수업 자료','정상'],['당첨 안내 확인','스팸']];
let current=0,model=null,preds=null,revealed=false;const words=t=>t.trim().split(/\s+/).filter(Boolean);const trainSet=()=>{let size=+$('#datasetSize').value;return size===8?DATA.slice(0,8):DATA};
function showStage(n){current=n;$$('.panel').forEach((p,i)=>p.hidden=i!==n);$$('[data-stage]').forEach((b,i)=>b.classList.toggle('active',i===n));$('#stageCount').textContent=`${n+1} / 4 단계`;$('#stageProgress').style.width=((n+1)*25)+'%';if(n===1)renderTrain();if(n===3)renderTests()}
$$('[data-stage]').forEach(b=>b.onclick=()=>showStage(+b.dataset.stage));$$('[data-next]').forEach(b=>b.onclick=()=>showStage(+b.dataset.next));
$$('#problemChoices button').forEach(b=>b.onclick=()=>{let ok=b.dataset.choice==='supervised';$('#problemFeedback').innerHTML=ok?'<b class="success">정답!</b> 정답 레이블이 있는 데이터를 통해 스팸/정상 두 범주를 예측하므로 지도학습의 분류입니다.':'<b class="danger">다시 생각해 보세요.</b> 여기에는 실제 정답 레이블이 있습니다. 정답이 있는 데이터를 활용해 범주를 예측하는 방식을 생각해 보세요.'});
function renderTrain(){ $('#trainRows').innerHTML=trainSet().map((r,i)=>`<tr><td>${i+1}</td><td>${r[0]}</td><td><span class="${r[1]==='스팸'?'danger':'success'}">${r[1]}</span></td><td>${words(r[0]).join(' · ')}</td></tr>`).join('')}
$('#datasetSize').onchange=()=>{resetAll();renderTrain();$('#prepFeedback').textContent='학습 자료 구성을 바꾸었으므로 모델을 다시 학습해야 합니다.'};$('#prepConfirm').onclick=()=>$('#prepFeedback').innerHTML=`<span class="success">확인 완료.</span> 훈련 데이터 ${trainSet().length}개와 별도로 보관된 테스트 데이터 ${TEST.length}개를 사용합니다.`;
function fit(rows){const labels=['스팸','정상'],vocab=[...new Set(rows.flatMap(r=>words(r[0])))];let counts={},totals={},ns={};labels.forEach(l=>{const rr=rows.filter(r=>r[1]===l);ns[l]=rr.length;counts[l]={};vocab.forEach(w=>counts[l][w]=0);rr.forEach(r=>words(r[0]).forEach(w=>counts[l][w]++));totals[l]=rr.reduce((s,r)=>s+words(r[0]).length,0)});return{labels,vocab,counts,totals,ns,n:rows.length}}
function classify(text){const tk=words(text);const scores={};model.labels.forEach(l=>{let score=Math.log(model.ns[l]/model.n);tk.forEach(w=>{if(model.vocab.includes(w))score+=Math.log((model.counts[l][w]+1)/(model.totals[l]+model.vocab.length))});scores[l]=score});let max=Math.max(...Object.values(scores)),den=Object.values(scores).reduce((s,v)=>s+Math.exp(v-max),0);let p=Object.fromEntries(Object.entries(scores).map(([k,v])=>[k,Math.exp(v-max)/den]));return{label:p['스팸']>=p['정상']?'스팸':'정상',p,known:tk.filter(w=>model.vocab.includes(w)),unknown:tk.filter(w=>!model.vocab.includes(w))}}
function resetEval(){preds=null;revealed=false;$('#revealAnswers').disabled=true;$('#numCorrect').textContent='—';$('#numWrong').textContent='—';$('#accuracy').textContent='—';$('#cm').hidden=true;$('#evalFeedback').textContent='먼저 테스트 메일을 예측하고, 실제 정답을 공개해 비교해 보세요.';renderTests()}
function resetAll(){model=null;$('#trainingFeedback').textContent='아직 모델을 학습하지 않았습니다.';$('#spamWords').innerHTML='<span>학습 전</span>';$('#hamWords').innerHTML='<span>학습 전</span>';$('#toEval').disabled=true;$('#predictTests').disabled=true;$('#predictCustom').disabled=true;$('#customFeedback').textContent='모델을 학습한 뒤 직접 분류할 수 있습니다.';$('#wordContributions').innerHTML='';resetEval()}
function wordTags(l){return Object.entries(model.counts[l]).sort((a,b)=>b[1]-a[1]).filter(x=>x[1]>0).slice(0,7).map(([w,n])=>`<span>${w} · ${n}회</span>`).join('')}
$('#trainModel').onclick=()=>{model=fit(trainSet());$('#trainingFeedback').innerHTML=`<b class="success">학습 완료!</b> 정답 레이블을 가진 훈련 메일 ${model.n}개에서 ${model.vocab.length}개 단어 특징의 등장 횟수를 학습했습니다. 각 범주의 학습 자료 ${model.ns['스팸']}개 / ${model.ns['정상']}개.`;$('#spamWords').innerHTML=wordTags('스팸');$('#hamWords').innerHTML=wordTags('정상');$('#toEval').disabled=false;$('#predictTests').disabled=false;$('#predictCustom').disabled=false;resetEval()};$('#resetModel').onclick=resetAll;
function renderTests(){ $('#testRows').innerHTML=TEST.map((r,i)=>{let pred=preds?preds[i].label:'—';let actual=revealed?r[1]:'🔒 비공개';let status=revealed?(pred===r[1]?'<span class="success">✓ 일치</span>':'<span class="danger">✕ 오분류</span>'):'—';return `<tr><td><b>${String.fromCharCode(65+i)}.</b> ${r[0]}</td><td>${pred}</td><td>${actual}</td><td>${status}</td></tr>`}).join('')}
$('#predictTests').onclick=()=>{if(!model)return;preds=TEST.map(r=>classify(r[0]));revealed=false;$('#revealAnswers').disabled=false;$('#evalFeedback').innerHTML='<b>예측 완료.</b> 아직 정답을 공개하지 않았습니다. 어느 메일에서 틀릴 것 같은지 먼저 예상해 보세요.';renderTests()};
$('#revealAnswers').onclick=()=>{if(!preds)return;revealed=true;renderTests();let correct=preds.filter((r,i)=>r.label===TEST[i][1]).length;$('#numCorrect').textContent=correct;$('#numWrong').textContent=TEST.length-correct;$('#accuracy').textContent=(100*correct/TEST.length).toFixed(1)+'%';$('#evalFeedback').innerHTML=`<b>평가 완료:</b> ${TEST.length}개 중 ${correct}개를 맞혀 정확도는 ${(100*correct/TEST.length).toFixed(1)}%입니다. <b>예측이 틀린 메일</b>이 무엇인지 확인하고 원인을 생각해 보세요. 테스트 데이터가 6개뿐이므로 실제 성능에 대한 확정적 결론은 내릴 수 없습니다.`;let cnt={ss:0,sn:0,ns:0,nn:0};TEST.forEach((r,i)=>{const actual=r[1]==='스팸'?'s':'n';const pred=preds[i].label==='스팸'?'s':'n';cnt[actual+pred]++});$('#cmRows').innerHTML=`<tr><th>스팸</th><td>${cnt.ss}</td><td>${cnt.sn}</td></tr><tr><th>정상</th><td>${cnt.ns}</td><td>${cnt.nn}</td></tr>`;$('#cm').hidden=false};$('#resetTests').onclick=resetEval;
$$('.sample').forEach(b=>b.onclick=()=>{$('#customText').value=b.dataset.text;$('#customText').focus()});$('#predictCustom').onclick=()=>{if(!model)return;const title=$('#customText').value.trim();if(!title){$('#customFeedback').textContent='메일 제목을 입력하세요.';return}const r=classify(title);$('#customFeedback').innerHTML=`<b>모델 예측:</b> <span class="${r.label==='스팸'?'danger':'success'}">${r.label}</span> · 모델 내부 점수 정규화값: 스팸 ${(r.p['스팸']*100).toFixed(1)}% / 정상 ${(r.p['정상']*100).toFixed(1)}%. <br><small>학습한 단어 ${r.known.length}개, 처음 보는 단어 ${r.unknown.length}개. 실제 스팸 확률이 아닙니다.</small>`;$('#wordContributions').innerHTML=r.known.map(w=>`<span>학습된 단어: ${w}</span>`).join('')+(r.unknown.map(w=>`<span style="background:#fff4dc">미등록 단어: ${w}</span>`).join(''));if(!r.known.length)$('#customFeedback').innerHTML+='<p class="warning">모델이 아는 단어가 없어 훈련 자료의 범주 비율만 반영됩니다. 예측을 신뢰하기 어렵습니다.</p>'};
renderTrain();renderTests();showStage(0);
''')
(a/'review.js').write_text(r'''"use strict";const questions=[{q:'정답 레이블이 있는 메일 데이터로 스팸/정상을 예측하는 것은?',a:['지도학습의 분류','지도학습의 회귀','비지도학습의 군집','강화학습'],ok:0,why:'정답 레이블로 학습하며 결과가 두 개의 범주이므로 지도학습의 분류입니다.'},{q:'학습에 사용하지 않은 별도 메일로 모델의 예측 성능을 확인할 때 쓰는 데이터는?',a:['훈련 데이터','테스트 데이터','결측치 데이터','전처리 전 데이터'],ok:1,why:'테스트 데이터는 학습된 모델이 새로운 사례에도 잘 작동하는지 평가할 때 사용합니다.'},{q:'정답 레이블 없이 구매 특성이 비슷한 고객끼리 묶는 방법은?',a:['지도학습의 회귀','지도학습의 분류','비지도학습의 군집','강화학습'],ok:2,why:'유사한 데이터를 정답 없이 묶는 작업은 비지도학습의 군집입니다.'},{q:'기계학습 모델의 올바른 구현 순서는?',a:['모델 평가→학습→데이터 수집→문제 정의','데이터 수집→평가→문제 정의→학습','모델 생성→전처리→평가→문제 정의','문제 정의→데이터 수집·전처리→모델 생성→모델 평가'],ok:3,why:'교과서 92쪽의 모델 구현 과정은 문제 정의, 데이터 준비, 모델 생성, 모델 평가의 순서입니다.'}];const answered={};function render(){ $('#quizMount').innerHTML=questions.map((q,i)=>`<div class="card" style="margin-bottom:16px"><span class="pill">${i<2?'Kahoot! 추천 문항':'추가 복습'}</span><h3>Q${i+1}. ${q.q}</h3>${q.a.map((x,j)=>`<button class="option" data-q="${i}" data-a="${j}">${j+1}. ${x}</button>`).join('')}<div id="fb${i}" class="qfeedback">정답을 선택하세요.</div></div>`).join('');$$('.option').forEach(b=>b.onclick=()=>{const i=+b.dataset.q,j=+b.dataset.a;if(i in answered)return;answered[i]=j;const q=questions[i];$$(`.option[data-q="${i}"]`).forEach(x=>{x.disabled=true;if(+x.dataset.a===q.ok)x.classList.add('correct');else if(+x.dataset.a===j)x.classList.add('incorrect')});$('#fb'+i).textContent=(j===q.ok?'✅ 정답! ':'🔍 다시 확인: ')+q.why;const n=Object.keys(answered).length;$('#quizSummary').textContent=n===questions.length?`총 ${questions.length}문항 중 ${questions.filter((q,k)=>answered[k]===q.ok).length}개 정답. 오답 해설을 확인해 보세요.`:`${n}/${questions.length}문항 완료`})}$('#restartQuiz').onclick=()=>{Object.keys(answered).forEach(k=>delete answered[k]);render();$('#quizSummary').textContent='처음부터 다시 시작했습니다.'};render();''')
(p/'README.md').write_text('''# 박채은 AI LAB — 다중 페이지 머신러닝 수업 사이트

고등학교 2학년 인공지능 기초, 교과서 88–92쪽에 기반한 15분 모의수업과 추가 탐구용 사이트입니다.

## 페이지
- `index.html` — 메인, 학습 목표, 단원 카드 및 수업 동선
- `types.html` — 지도/비지도/강화학습, 분류·회귀·군집·연관 규칙, 유형 선택 실습
- `workflow.html` — 모델 구현의 네 단계, 데이터 전처리, 정확도
- `lab.html` — 훈련 데이터 선택, **실제 다항 나이브 베이즈 분류기 계산**, 테스트 데이터 예측·평가, 혼동행렬, 자유 입력
- `review.html` — 정리·연습 퀴즈 및 Kahoot! 연결

## 사용 및 배포
1. ZIP을 해제한 뒤 `index.html`을 열어 로컬에서 학습합니다. HTML·CSS·JavaScript로 작성되어 외부 서버가 필요 없습니다. (인터넷이 끊기면 웹 글꼴 대신 시스템 글꼴로 표시됩니다.)
2. GitHub에서 **공개** 저장소 `parkchaeeun-ai-lab` 등을 생성합니다.
3. ZIP 내부의 `index.html`, `types.html`, `workflow.html`, `lab.html`, `review.html`, `assets/` 폴더를 **파일 구조 그대로** 업로드합니다.
4. Settings → Pages → Deploy from a branch → `main` / `(root)` → Save.
5. 배포가 완료되면 `https://<GitHub-ID>.github.io/<저장소명>/`으로 접속합니다.

## 수업 권장 동선
- 메인 1분 → 학습 유형 4분 → 모델 구현 2분 → 실습 4분 → 학습지·Kahoot! 3분 (+ 도입 이동 1분 등)
- 교사는 대표 시연을 진행하고 학생은 결과를 예측·설명하는 방식으로 모의수업을 운영합니다.
- 실습에서는 학습 데이터 16개를 선택하고, **학습 → 6개 테스트 예측 → 정답 공개 및 정확도 확인**을 중심으로 시연합니다.
- 추가 실습(훈련 데이터 크기 비교, 새로운 메일 자유 입력, 혼동행렬)은 수업 후 탐구에도 적합합니다.

## 교육적 한계
- 모든 데이터는 가상이며 분류기가 실제 메일을 판정하는 데 쓰일 수 없습니다.
- 단어를 공백 기준으로 구분하는 간단한 다항 나이브 베이즈 분류기입니다. 미등록 단어는 점수에서 제외합니다.
- 모델의 내부 점수는 실제 세계의 정확한 스팸 확률을 뜻하지 않습니다.
- 테스트 데이터 6개만으로 일반적 성능을 확정할 수 없습니다.
- 기존 참고 사이트의 소스코드·문구·이미지는 복제하지 않고 독립적으로 구현했습니다.
''')
